'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Button, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './button.css'

import { LockGlyph } from './glyphs'

/**
 * Button: the action a player takes that is not a choice.
 *
 * Start, continue, play again, claim, share. `choice` is for picking between
 * options; this is for committing to the one thing on offer.
 *
 * Five treatments, which with the large size are the six specimen 1f draws:
 * `primary`, `secondary`, `tertiary` for a dismissal, `destructive` for an
 * action that warns, and `icon` for a square control holding one glyph.
 *
 * It performs nothing. It does not navigate, submit, fetch or decide. It
 * renders a control and reports the press. Everything behind the press is the
 * host's.
 *
 * Two states are separate on purpose (BDS-013). Disabled goes flat: not
 * available at all. Locked keeps its shape and shows a padlock: available
 * later, not now. A player can tell "not yet" from "not ever" at a glance,
 * which is why they are two attributes rather than one.
 */

export type ButtonVariant = 'primary' | 'secondary' | 'tertiary' | 'destructive' | 'icon'

/** The contract's three steps. `small` is the 44px control on a state card. */
export type ButtonSize = 'small' | 'default' | 'large'

interface ButtonCommonProps
  extends Omit<React.ButtonHTMLAttributes<HTMLButtonElement>, 'disabled'> {
  /** Large is the hero action: start, play again, claim. */
  size?: ButtonSize
  /** Not available at all. Goes flat, takes no focus. */
  disabled?: boolean
  /**
   * Available later, not now. Keeps its shape, shows a padlock, stays
   * focusable. Ignored when `disabled` is also set: "not available at all" is
   * the stronger claim, and a control cannot be flat and keep its shape at once.
   */
  locked?: boolean
}

/** Any button carrying words: four emphasis levels, loudest to quietest. */
export interface LabelledButtonProps extends ButtonCommonProps {
  /**
   * `primary` is the one action on the surface, `secondary` everything beside
   * it, `tertiary` the dismissal that must not weigh as much as the thing it
   * declines, and `destructive` the action that warns rather than invites.
   */
  variant?: Exclude<ButtonVariant, 'icon'>
  /** Only an icon control takes a label; a labelled one has its children. */
  label?: never
}

/** A square control holding one glyph and no words. */
export interface IconButtonProps extends ButtonCommonProps {
  variant: 'icon'
  /**
   * What the control does, in words. Required, because a glyph is a drawing
   * and a drawing is not a name: without this the only thing a screen reader
   * could announce is "button".
   */
  label: string
}

export type ButtonProps = LabelledButtonProps | IconButtonProps

/**
 * The implementation sees one shape. Both members of the union are assignable
 * to it, so this widens without a cast and `tsc` still refuses an icon control
 * with no label at every call site.
 */
type ButtonImplProps = ButtonCommonProps & { variant?: ButtonVariant; label?: string }

// The glyph, because a state that is only a colour is not a state, is
// `LockGlyph` from `@gamestage/glyphs`. It was a colour emoji padlock, which
// painted itself gold on an arcade-blue control and changed silhouette per
// operating system (GSUI-103). The character is not repeated here: the gate
// greps the source for emoji, and a mention would read as a use.

const STATE_LABEL = { locked: 'locked' } as const

export function Button(props: ButtonProps) {
  const {
    variant = 'primary',
    size = 'default',
    disabled = false,
    locked = false,
    label,
    className,
    children,
    onClick,
    type = 'button',
    ...rest
  }: ButtonImplProps = props

  // Locked stays in the tab order. "Available later" is something a player
  // should be able to reach and hear described. Only disabled, which is never
  // coming back on this surface, leaves.
  //
  // Disabled wins when both are set. BDS-013 gives them contradictory
  // renderings, flat against keeps-its-shape, so a control carrying both would
  // have to break one of them; and a padlock on something that is never coming
  // back tells the player the opposite of the truth.
  const isIcon = variant === 'icon'
  const isLocked = locked && !disabled
  const unpressable = disabled || isLocked

  const stateWord = isLocked ? STATE_LABEL.locked : undefined

  // aria-disabled does not stop an event the way the native attribute does, so
  // a locked control has to refuse them itself. Every press handler, not only
  // onClick: a host's onKeyDown or onPointerDown would otherwise fire on a
  // control the player has been told they cannot use yet.
  //
  // Refusing means not calling the host's handler. It does not mean
  // preventDefault, which is reserved for the click below. Cancelling mousedown
  // would suppress the browser's own click-to-focus, so a player who clicked a
  // locked control would not focus it and would never hear it described.
  function refuseWhenUnpressable<E extends React.SyntheticEvent>(
    handler: ((event: E) => void) | undefined,
  ) {
    return (event: E) => {
      if (unpressable) return
      handler?.(event)
    }
  }

  return (
    <button
      {...rest}
      type={type}
      className={['gs-button', 'gs-action-type', 'gs-pressable', className].filter(Boolean).join(' ')}
      data-gs-component="button"
      data-gs-variant={variant}
      data-gs-size={size}
      data-gs-disabled={disabled ? 'true' : undefined}
      data-gs-locked={isLocked ? 'true' : undefined}
      // The control moves on press and does not otherwise animate, so it is
      // motion. The padlock is emphasis and survives reduced motion, which is
      // how a player who cannot see movement still sees that it is locked.
      data-gs-animates="motion"
      disabled={disabled}
      aria-disabled={unpressable || undefined}
      // Enter and Space arrive as a synthesised click on a native button, so
      // guarding onClick covers the keyboard as well as the pointer. The rest
      // are guarded because a host may hang its own behaviour on any of them.
      //
      // Click is the one that also cancels: a host may override type to submit,
      // and a locked control must not submit a form.
      onClick={(event) => {
        if (unpressable) {
          event.preventDefault()
          return
        }
        onClick?.(event)
      }}
      onKeyDown={refuseWhenUnpressable(rest.onKeyDown)}
      onKeyUp={refuseWhenUnpressable(rest.onKeyUp)}
      onPointerDown={refuseWhenUnpressable(rest.onPointerDown)}
      onPointerUp={refuseWhenUnpressable(rest.onPointerUp)}
      onMouseDown={refuseWhenUnpressable(rest.onMouseDown)}
      onMouseUp={refuseWhenUnpressable(rest.onMouseUp)}
      onTouchStart={refuseWhenUnpressable(rest.onTouchStart)}
      onTouchEnd={refuseWhenUnpressable(rest.onTouchEnd)}
    >
      {/* An icon control's children are its glyph, and a glyph is hidden from
          the name: the gallery's naming check zeroes out aria-hidden subtrees
          for exactly this case, so a visible drawing would otherwise read as a
          name while a screen reader announced nothing a player could act on.
          A locked icon control shows the padlock instead of its glyph, because
          a 56px face has room for one mark and "not yet" is the one that
          matters. */}
      {/* The padlock comes before the word: specimens 1f and 2b draw "Level 8"
          and "Lv 8" with the mark first, and a locked icon control shows only
          the mark. It is hidden from the name; the locked word below carries
          the state to a screen reader. */}
      {isLocked ? (
        <span className="gs-button__glyph" data-gs-animates="emphasis" aria-hidden="true">
          <LockGlyph />
        </span>
      ) : null}
      {isIcon ? (
        isLocked ? null : (
          <span className="gs-button__glyph" aria-hidden="true">
            {children}
          </span>
        )
      ) : (
        <span className="gs-button__label">{children}</span>
      )}
      {/* The label is content rather than aria-label on purpose. aria-label
          replaces the whole computed name, so the locked word below would
          vanish and a locked pause control would announce itself as available. */}
      {isIcon && label ? <span className="gs-button__announcement">{label}</span> : null}
      {/* The state belongs in the accessible name, and children are arbitrary
          nodes, so it cannot go in aria-label without stringifying them. No
          separator here: the span is absolutely positioned, which blockifies
          it, and a browser inserts the space itself during name computation. */}
      {stateWord ? <span className="gs-button__announcement">{stateWord}</span> : null}
    </button>
  )
}

/* Button. Every value comes from a token; nothing here is a literal colour. */

.gs-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--gs-space-2);
  position: relative;

  /* 48px is the smallest target a thumb reliably hits; the action sizes are
     above it, and this is the floor if a host shrinks one. */
  min-height: var(--gs-size-action);
  min-width: var(--gs-size-touch-min);
  padding: 0 var(--gs-space-6);

  text-align: center;

  /* Every control carries the outline token in edge: arcade draws a 3px edge
     ring on every face in specimen 2b, base a 1px hairline. The base drawing
     (1f) outlines none of its filled faces, which is a 1px gap design/twins/1f
     tolerates and names as a token request (stroke.face). */
  border: var(--gs-stroke-control, var(--gs-stroke-hairline)) solid var(--gs-color-edge);
  /* 16px: the radius the drawing gives every 56 to 60px control (1f, 2b). */
  border-radius: var(--gs-radius-control);
  cursor: pointer;

  /* Only the movement is timed here. The padlock's transition lives on the
     emphasis element so it survives reduced motion. */
  transition: transform var(--gs-motion-press) ease-out,
              box-shadow var(--gs-motion-press) ease-out;
}

.gs-button[data-gs-size='large'] {
  min-height: var(--gs-size-action-large);
  padding: 0 var(--gs-space-8);
  /* 18px on the 64 and 68px faces, 1f and 2b: the step above radius.control. */
  border-radius: var(--gs-radius-lg);
}

/* The drawing spaces only the primary action's letters: 1f sets .01em on Play
   and nothing on Skip round, Not now, Quit game or Level 8, and 2b does the
   same with .02em on Start. The action token carries one letter-spacing, so
   the others give it back. */
.gs-button:not([data-gs-variant='primary']),
.gs-button[data-gs-locked='true'],
.gs-button[data-gs-disabled='true'] {
  letter-spacing: normal;
}

/* The small step of the scale, which had no rule and rendered at the default:
   specimen 4e's state cards carry 44px controls, 12px round, padded 18, and
   `size="small"` is what the contract names for them. The ghost keeps its own
   height rule below, which is why it is repeated for it here. */
.gs-button[data-gs-size='small'],
.gs-button[data-gs-variant='tertiary'][data-gs-size='small'] {
  min-height: var(--gs-size-control-medium);
  padding: 0 var(--gs-space-4);
  border-radius: var(--gs-radius-sm);
}

/* The small ghost keeps half the padding, as the large one does. */
.gs-button[data-gs-variant='tertiary'][data-gs-size='small'] {
  padding: 0 var(--gs-space-3);
}

.gs-button:focus-visible {
  outline: var(--gs-stroke-focus) solid var(--gs-color-ink);
  outline-offset: 3px;
}

/* -- primary -------------------------------------------------------------- */
/* An offset base, not a shadow. The base collapses and the face performs
   press.transform, whose default travels the same press.travel the base was
   offset by, so the face lands where the base was. A theme may swap the
   gesture for a scale or for no movement at all. */
.gs-button[data-gs-variant='primary'] {
  color: var(--gs-color-on-accent);
  background: var(--gs-color-interactive);
  box-shadow: var(--gs-depth-pressable);
}

.gs-button[data-gs-variant='primary']:hover:not([aria-disabled='true']) {
  background: var(--gs-color-interactive-hover);
}

/* Pressable controls never fade or darken. They perform the theme's press
   gesture: a 6px drop by default, `none` under reduced motion. */
.gs-button[data-gs-variant='primary']:active:not([aria-disabled='true']) {
  transform: var(--gs-press-transform);
  box-shadow: var(--gs-depth-pressable-pressed);
}

/* The large primary is the game action, and the drawing paints it positive:
   green GO and PLAY on 1f, 1g and 2b, where the ordinary primary is the
   interactive colour. Its shelf is depth.pressablePositive so the base under
   it matches the face. Set directly rather than through the pressable bundle,
   which carries one shadow per depth style. GSUI-179. */
.gs-button[data-gs-variant='primary'][data-gs-size='large'] {
  color: var(--gs-color-on-bright);
  background: var(--gs-color-positive);
  box-shadow: var(--gs-depth-pressable-positive);
}

.gs-button[data-gs-variant='primary'][data-gs-size='large']:hover:not([aria-disabled='true']) {
  background: var(--gs-color-positive);
}

.gs-button[data-gs-variant='primary'][data-gs-size='large']:active:not([aria-disabled='true']) {
  box-shadow: var(--gs-depth-pressable-positive-pressed);
}

/* -- secondary ------------------------------------------------------------ */
/* Raised rather than offset, so it reads as the lesser action without being
   dimmer: a dim control reads as disabled. It travels the depth it has. */
.gs-button[data-gs-variant='secondary'] {
  color: var(--gs-color-ink);
  background: var(--gs-color-surface-raised);
  box-shadow: var(--gs-depth-raised);
}

.gs-button[data-gs-variant='secondary']:hover:not([aria-disabled='true']) {
  border-color: var(--gs-color-edge-high);
}

.gs-button[data-gs-variant='secondary']:active:not([aria-disabled='true']) {
  transform: var(--gs-press-transform);
  box-shadow: var(--gs-depth-flat);
}

/* -- tertiary ------------------------------------------------------------- */
/* The ghost. Text, no box, no stroke, and the smallest of the three heights,
   because the design draws it at 48 while primary and secondary sit at 56.
   A dismissal has to be reachable without weighing as much as the thing it
   declines, so it gives up its shape rather than its contrast: it keeps a
   readable ink and grows a face only under the finger. */
.gs-button[data-gs-variant='tertiary'] {
  min-height: var(--gs-size-touch-min);
  /* Half the padding the boxed treatments carry. The base rule's 24px is there
     to give a filled face room around its words; a ghost has no face to give
     room in, and at 24px a two-word dismissal measured wider than the drawing's
     does. The 48px min-width from the base rule stays: it is the touch floor,
     and a ghost is still something a thumb has to hit. */
  padding: 0 var(--gs-space-4);
  color: var(--gs-color-ink-secondary);
  background: transparent;
  border: 0;
  /* 14px, the compact radius: the drawing rounds the 48px ghost tighter than
     the 56px faces beside it. */
  border-radius: var(--gs-radius-md);
  box-shadow: var(--gs-depth-flat);
}

/* A ghost keeps its shape by having none. The shared locked and disabled rules
   below hand every control a face and a depth, which is right for a treatment
   that had one and wrong here: it would grow a box at the moment the file's own
   comment says the control keeps its shape. So tertiary opts out of the face
   and keeps only the ink change, which is the whole of its vocabulary. */
.gs-button[data-gs-variant='tertiary'][data-gs-locked='true'],
.gs-button[data-gs-variant='tertiary'][data-gs-disabled='true'] {
  background: transparent;
  border-color: transparent;
  box-shadow: var(--gs-depth-flat);
}

.gs-button[data-gs-variant='tertiary']:hover:not([aria-disabled='true']) {
  color: var(--gs-color-ink);
  background: var(--gs-color-surface);
}

/* No base to collapse, so the press is a squeeze rather than a drop. */
.gs-button[data-gs-variant='tertiary']:active:not([aria-disabled='true']) {
  background: var(--gs-color-surface-raised);
  transform: scale(0.97);
}

/* -- destructive ---------------------------------------------------------- */
/* A red outline on a bare face. It is the only control that warns rather than
   invites, so it is drawn in the negative colour and left hollow: a filled red
   button at rest reads as the thing to press, which is the opposite of what
   "Quit game" wants. It fills on press, at the moment the player has committed.

   `--gs-color-negative-solid` rather than `--gs-color-negative` in `color` and
   `border-color`, because the arcade theme sets negative to a gradient and a
   gradient substituted into a colour property drops the whole declaration. */
.gs-button[data-gs-variant='destructive'] {
  color: var(--gs-color-negative-solid);
  background: transparent;
  border: var(--gs-stroke-ui) solid var(--gs-color-negative-solid);
  box-shadow: var(--gs-depth-flat);
}

/* The drawing tints the face 12% on hover. Mixed from the token rather than
   written as a colour, so a theme changing negative reaches this too. */
.gs-button[data-gs-variant='destructive']:hover:not([aria-disabled='true']) {
  background: color-mix(in oklch, var(--gs-color-negative-solid) 12%, transparent);
}

.gs-button[data-gs-variant='destructive']:active:not([aria-disabled='true']) {
  color: var(--gs-color-on-accent);
  background: var(--gs-color-negative);
  transform: scale(0.97);
}

/* A locked or disabled destructive loses its red, because the shared rules below
   set the border colour and the ink, and that is correct rather than incidental:
   a control the player cannot press is not warning them about anything. What it
   keeps is the outline's shape, which is what says it is still a button. */

/* -- icon ----------------------------------------------------------------- */
/* A square face holding one glyph: pause, mute, help. Square rather than the
   label shape, so `width` is pinned to the same token `min-height` reads and
   the padding that makes room for words is taken away.

   It takes the secondary paint on purpose. These are utility controls beside
   the action rather than the action itself, and the drawing gives the pause
   control the same raised face, high edge and collapsing base that secondary
   has. The drawing also draws the same shape twice more, filled and bare, at
   two other emphases; one variant value can only be one of them, and widening
   it is GSUI-178. */
.gs-button[data-gs-variant='icon'] {
  width: var(--gs-size-action);
  min-width: var(--gs-size-action);
  padding: 0;
  border-radius: var(--gs-radius-full);
  color: var(--gs-color-ink);
  background: var(--gs-color-surface-raised);
  box-shadow: var(--gs-depth-raised);
}

.gs-button[data-gs-variant='icon'][data-gs-size='large'] {
  width: var(--gs-size-action-large);
  min-width: var(--gs-size-action-large);
  padding: 0;
}

.gs-button[data-gs-variant='icon']:hover:not([aria-disabled='true']) {
  background: var(--gs-color-surface);
}

.gs-button[data-gs-variant='icon']:active:not([aria-disabled='true']) {
  transform: var(--gs-press-transform);
  box-shadow: var(--gs-depth-flat);
}

/* -- locked and disabled -------------------------------------------------- */
/* Locked keeps its shape and shows a padlock: available later, not now.

   The shape is the geometry: the same height, radius and outline as the face
   it was. The paint is the disabled paint. That is what the drawing draws, in
   1f, 1g and 2b alike: "Level 8" and "Lv 8" sit on color.disabled in
   disabledInk with no base under them and a padlock before the word, and the
   design's note beside them says "locked buttons keep their shape and show a
   padlock; only disabled goes flat". design/twins/1f measures ours against it.

   An earlier reading gave locked the raised secondary face, which made a locked
   control look pressable with a padlock on it. The padlock, not the fill, is
   what separates locked from disabled: "not yet" against "not ever". */
.gs-button[data-gs-locked='true'],
.gs-button[data-gs-disabled='true'] {
  cursor: not-allowed;
  color: var(--gs-color-disabled-ink);
  background: var(--gs-color-disabled);
  box-shadow: var(--gs-depth-flat);
}

.gs-button__label { font: inherit; }

.gs-button__glyph {
  /* inline-flex, so the span is exactly the 1em square the glyph draws: as an
     inline box it carried the line's descender space and measured 26px for a
     24px mark. */
  display: inline-flex;
  font-size: var(--gs-size-icon-control);
  line-height: 1;
  /* Emphasis, not motion: this duration survives reduced motion on purpose. */
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

/* A padlock beside a word is a utility mark, drawn at 14px in 1f and 2b; the
   24px control size is for the one glyph an icon control is built around. */
.gs-button:not([data-gs-variant='icon']) .gs-button__glyph {
  font-size: var(--gs-size-icon-utility);
}

/* Read by a screen reader, never seen. `display: none` would drop it from the
   accessible name, which is the one thing this element is for. */
.gs-button__announcement {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  white-space: nowrap;
  clip-path: inset(50%);
  border: 0;
}
